-- Generated source references; not native quest records.
local addon = WordHunterWoW_Addon
local compat = addon and addon.Compat
local flavor = compat and compat.GameFlavor and compat.GameFlavor()
if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[40183] = { id = 40183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Over Your Head", description = "Alright, {name}, I'd like you to assist me with creating a helm.\n\nFirst we'll need to shave the hides, then tan them, and finally cut them into usable pieces.\n\nFollow my lead.", progress = "I'm starting to think we make a pretty good team.", completion = "Well done, {name}. Here's a copy of that pattern to add to your collection.\n\nI personally specialize in softer leather armor. If you want to make a MAIL helm, talk to Ranid... although I'm sure he'll charge you a pretty penny for it.", objectives = "Craft a Rough Warhide Mask.\n\nYou will need to use Namha's Tanning Rack and Namha's Workbench, located in Legendary Leathers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40184] = { id = 40184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tauren Tanning", description = "Have you heard of the Highmountain tauren tribes? They're not unlike the tauren we know on Kalimdor.\n\nI've heard they have a leatherworking master there who might be able to help us come up with some new patterns.\n\nTravel to Highmountain and see if they're willing to teach you how they craft their armor.", completion = "I can smell the leather on you, stranger.\n\nIt's in your skin, your bones, your spirit. It's also clear to these eyes that you wish to know about the leather of these lands.\n\nIf that's the case... then I must test your grain.", objectives = "Report to Hrul Sharphoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40185] = { id = 40185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shoulder the Burden", description = "During one of our recent battles, my brother, Lohrumn, was slain. His armor was taken by the drogbar.\n\nYou would honor his memory by retrieving what has been stolen. I will make it worth your while, leatherworker.", progress = "My brother's armor... have you found it?", completion = "Thank you, {name}. As promised, let me teach you one of our crafts.", objectives = "Obtain Lohrumn's Shoulderguard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40186] = { id = 40186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drogbar Durability", description = "We are currently at war with a race known as the drogbar. We have long maintained peace with the drogbar, but lately, they have no respect for anyone but themselves.\n\nSlay them. Prove your worth as an ally of the tauren. Do this, and I will reward you with knowledge.", completion = "If you can take down the drogbar, then perhaps you are worthy of my knowledge.\n\nI'll start you with a couple simple patterns to start.", objectives = "Kill 15 drogbar to prove your worth to Hrul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40187] = { id = 40187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Links in the Chain", description = "Well, <lad/lass>, I'm afraid I'm at me wits' end with these scales. Not quite sure how to fashion the remaining pieces fer a full set.\n\nHowever, I've heard that the elves of Azsuna had some great crafters in their cities. Perhaps one or two of them still exist.\n\nGo there and search fer a master. Maybe they can fill in the missing patterns fer us.", completion = "Yes, {class}? You seek to know the techniques of crafting elven mail?\n\nI see. Perhaps a bargain can be struck to benefit us both.", objectives = "Find a leatherworking master in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40188] = { id = 40188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Best Served Cold", description = "My partner and I both fell victim to the fallout of the Sundering. We were betrayed and abandoned by a trusted friend.\n\nThat \"friend\" has recently appeared in the ruins to the east. His name is Ranaris.\n\nGo to and take revenge for us and I will grant you some of my wisdom.", completion = "You are a man of your word, {name}. I thank you for your service to us.\n\nAnd as we agreed, I shall pass on some of my wisdom to you.", objectives = "Kill Ranaris in the El'dranil Shallows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40189] = { id = 40189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naga Know-How", description = "The naga of this region wear little armor, but what they do wear is particularly durable.\n\nIf you wish to make a strong shoulder piece, I would first study the naga's armor and then create a pattern of similar construct.\n\nThe city nearby is overrun by naga. Slay them and bring me their armor and I will show you what I mean.", progress = "They may be vile, but they still know how to craft as well as any master.", completion = "These are good pieces. Look here...\n\n<Celea begins to explain the armor's construction to you.>\n\n...and with that, I trust you can create something of equal quality.", objectives = "Obtain 7 Naga Shoulderguards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40190] = { id = 40190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hardening the Hide", description = "Back to Highmountain for you, {name}! I hear they know even more efficient ways to craft our patterns.\n\nWhen you get there, put in a good word for me, will ya? I'd like to start a relationship the tauren, so I don't have to keep sending you back and forth.", completion = "Come for more lessons, {name}?\n\nVery well. Let us begin.", objectives = "Return to Highmountain and talk to Hrul Sharphoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40191] = { id = 40191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stamped Stories", description = "Stamped onto the leather of the tanning racks behind me are the ancient ways of our tribe's leatherworkers.\n\nThey tell the stories of masters who, through perseverance - and luck, in some cases - pioneered our way of leatherworking.\n\nRead the stories and learn from them. Perhaps you'll find some insight on how to better your own methods.", completion = "I see hope in your eyes, {name}. I take it our lessons of the past will aid you with your future?", objectives = "Learn from the stories of each of the tanning racks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40192] = { id = 40192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claw of the Land", description = "Personal experience has taught me to use stronger materials when crafting armor pieces. They last longer, and you don't need quite as many of them.\n\nFor example, I utilize the claws of the pinerock stalkers. If you acquire some for me, perhaps I can show you how better materials can increase your efficiency.", progress = "Their claws are some of the strongest I've ever come across.", completion = "You've gathered enough here to last me for many moons.\n\n<Hrul begins to work with the claws. It's clear that he's using very little of each, but still able to make an excellent armor piece.>\n\nI hope you were able to learn something from this, {name}.", objectives = "Obtain 100 Stalker Claws.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40193] = { id = 40193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting the Kinks Out", description = "Now listen, <lad/lass>. Everything ye make can always be done better. I just haven't quite worked out the way to do it with these fancy new scales.\n\nPerhaps that ghost-like elf friend of yours can help ye. An' if she DOES know somethin', perhaps ye can relay that information back to us.\n\nIt would certainly go towards making the shop more lucrative.", completion = "Back so soon, {name}?\n\nAhh... you wish to master your existing patterns. That's the characteristic of a true leatherworker.\n\nYes, I can help you.", objectives = "Go back to Celea in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40194] = { id = 40194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaimed Cargo", description = "The same ship that my brother was on also carried shipments of exceptional mail armor. Knowing the giants, they probably had no use for them and left them scattered around their caves.\n\nIf you could recover those shipments and bring them here, I can explain the techniques used to fashion them. That should give you a good idea of how to improve your processes.", progress = "Were you able to recover any of the shipments?", completion = "They're a bit rusty, but at least they're intact. Let me explain how these were made...\n\n<Celea begins to describe the method in which the armor was constructed.>\n\nTedious, yet efficient.", objectives = "Obtain 5 Mail Armor Shipments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40195] = { id = 40195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Daring Rescue", description = "My brother, Taldranis, was on a ship headed here to Azsuna. The ship was ambushed by the sea giants and my brother was taken captive.\n\nI believe he still lives out his days in those horrible caves, slaving away for the giants. Go and free him, please.\n\nTake this with you, it may give him enough protection should you run into any trouble. And be careful not to get captured by the giants yourself.", completion = "Wait, Celea sent you? I thought she had been lost ages ago.", objectives = "Find Taldranis in Oceanus Cove, and deliver the armor to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40196] = { id = 40196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventuring Anxieties", description = "{name}! I was recently talking with Mei, the mount trader, and she asked me if it was possible to make a barding that could prevent adventurers from being dismounted.\n\nI'd like you to go and discuss this idea with her further.\n\nReturn to me when you're finished. Perhaps we can solve this issue together.", completion = "I see.\n\nThat shouldn't be too difficult to make.", objectives = "Speak with Mei Francis about her barding idea.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40197] = { id = 40197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Necessary Materials", description = "In order to make this barding, we'll need a lot of leather. And I mean a LOT of leather.\n\nI'll solidify our plans on fitting the pieces together. You go gather the leather.\n\nOnce that's done, we can begin crafting.", progress = "This is probably the biggest project I've ever been a part of. It's quite exciting!", completion = "I've got the plans. You have the leather?", objectives = "Gather 100 Stonehide Leather.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40198] = { id = 40198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rats!", description = "I tell you, {name}, I have the worst luck sometimes.\n\nA package recently arrived from Hrul containing leatherworking patterns, and while my back was turned, some filthy rats came in and ran off with them down into the sewers!\n\nProbably building nests with them as we speak. Please, {name}, can you go down there and see if you can retrieve any of them?", progress = "I hope they're not too badly damaged.", completion = "Nice work stitching these back together. Too bad you couldn't get all the rat saliva off of them.\n\nLet's read them together, shall we?", objectives = "Go into the Underbelly and recover 3 Highmountain Leatherworking Patterns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40199] = { id = 40199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leather Legwork", description = "Good news, {name}! Langrom's Leather and Links recently delivered a shipment of mail armor to me.\n\nIt's of the finest quality and I'd love to show it to ye, but it seems I've lost me crowbar and can't open the crate.\n\nIf ye could run over to their shop and grab an extra one fer me, we can get this crate opened and go over the construction.", progress = "Fer the life of me, I dunna know where I left the blasted thing!", completion = "Well wouldn't ye know it, {name}. While ye were out, I found me crowbar! Isn't that great news?\n\nOh, ye were able to acquire one too? Ha ha!\n\nWell why don't ye hold onto that fer yerself and have a look at these armor pieces with me.", objectives = "Get a crowbar for Thanid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40200] = { id = 40200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Bonds", description = "Do you like pets, {name}? I love pets. They're so cute!\n\nBut what I really want is more things with which to play with them.\n\nI'm sure Lio over at the Magical Menagerie has some ideas for fun toys. You should go talk to her!", completion = "Oh, those are good ideas! Let's get started.", objectives = "Talk to Lio the Lioness at the Magical Menagerie shop. Then return to Namha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40201] = { id = 40201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playthings", description = "Ok, so her ideas were a leash, a bed, and a FLAMING HOOP?!\n\nIt sounds like they want to start a circus or something. Regardless, I love all those ideas and we should get started as soon as you're ready.\n\nWhy don't you work on making the bed, and I'll work out the details for the flaming hoop.", progress = "Make sure it's nice and cozy!", completion = "Awww, my pets are going to look so cute sitting on this. Well, most of them will. Probably not all of them.", objectives = "Craft a prototype for the pet bed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40202] = { id = 40202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Lessons", description = "{name}, Hrul has requested your presence. From his message it seems as though he's ready to impart to you all the wisdom he has gained from working with the skins of this land.\n\nI envy you, {name}... but I'm also proud to see that you've gained so much respect with him.\n\nGo now, and good luck!", completion = "This will be the last of what I have to teach.\n\nAre you ready for the trials that await you?", objectives = "Go to Hrul Sharphoof in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40203] = { id = 40203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strength of the Past", description = "As you know, the durability of your armor is only as strong as the materials you use to make them.\n\nLong ago, the black dragon, Deathwing once inhabited this very mountain. In his quest for power, his body began to tear and he had creatures make metal scales to stitch his wounds.\n\nHis natural scales fell to the ground in his lair and have been there ever since. Go retrieve a scale and bring it to me.\n\nThis will take all your strength to accomplish.", progress = "True strength isn't determined by how much you can endure, but by continuing to endure when you lack the strength.", completion = "You never cease to disappoint me, {name}.\n\nAnd now I impart to you sacred knowledge which was once passed unto me.", objectives = "Return a scale of Deathwing to Hrul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40204] = { id = 40204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evolution of the Past", description = "As we make stronger armor, the creatures we battle adapt and learn to defeat us. We in turn create better armor, and they in turn learn to defeat it yet again.\n\nFor centuries, my people have battled the basilisks of the mesas below. They have adapted to us as thoroughly as we have to them.\n\nGo, kill these basilisks and take from them their hides. Return them to me so I may show you how they have evolved.", progress = "Do not fear change, for change is the only way to move forward.", completion = "See this, {name}? What was once a soft, simple scale...\n\n\n\n...has evolved into a jagged weapon that can kill!\n\n<He then indicates to the spined scales at the base of the creature's neck.\n\nI trust you now understand the purpose of change.", objectives = "Obtain 5 Basilisk Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40205] = { id = 40205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Respect for the Past", description = "We record the mistakes of the past so we can learn to avoid them in the present. However, recording history is not just about preventing missteps, but also to celebrate our successes.\n\nScattered around Highmountain at sacred locations are racks with stamped leather, much like the ones here, with stories to tell.\n\nGo to these locations, pay your respect, and learn their lessons.", completion = "You look wiser, {name}. The ancestors clearly deemed you worthy of their lessons...\n\n...as do I.", objectives = "Go to the four tanning racks around Highmountain and hear their stories.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40206] = { id = 40206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Debt Paid", description = "Now, I've never heard of a ghost sending a letter before, but I'll be damned if'n I didn't just receive one now.\n\nCelea has sent fer ye, <lad/lass>. I'd best be on me way if I were ye. Might be bad luck to keep a spirit waiting.", completion = "Thank you for coming, {name}. I wish to impart to you the remainder of my wisdom.", objectives = "Go to Celea in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40207] = { id = 40207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scales of the Arcane", description = "In my experience, dragon scale has been the strongest material I've ever had the privilege of working with. It's hard, durable and very little can go a long way.\n\nI wish to work with it again, {name}. Being in this form, I'm bound to this area, unable to experience the world any longer.\n\nI've heard rumor of the blue dragonflight occupying parts of Azsuna. Perhaps you can speak with them and see if they can shed a scale or two.", progress = "To work with dragon scale again would be a great honor.", completion = "Yes, these are perfect, {name}. As is fair, I will return this grand favor and impart more of my leatherworking knowledge to you.", objectives = "Speak with the blue dragonflight and acquire one of their scales.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40208] = { id = 40208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye of Azshara: Scales of the Sea", description = "When we first met, I spoke of the naga, and the armor they're able to craft. No grander armor is worn, however, than by their top warlords.\n\nOne in particular resides within the Eye of Azshara itself. His name is Warlord Parjesh, and the hauberk he wears is one of legend.\n\nRepel his forces, and obtain his armor. Do this, and I will teach you more of the Azsunian way of leatherworking.", progress = "He will not just hand it over, {name}. You're in for a rough fight.", completion = "You've taken down a mighty adversary, {name}. The naga no doubt will be on the hunt for you.\n\nBefore they get to you though, allow me to show you a few things...", objectives = "Go to the Eye of Azshara and obtain Warlord Parjesh's Hauberk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40209] = { id = 40209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scales of the Earth", description = "While leather armor is strong on its own, integrating scales into the design is what truly sets it apart.\n\nThe type of scales you use will determine how many you'll need to fully protect the wearer. And one of the strongest type of scales are basilisk scales.\n\nA fully matured basilisk has the strongest of course. Near the village of Llothien is a basilisk den. Kill the matriarch and return her scales to me.", progress = "You may have to fight past a few of her brood to get to her.", completion = "The basilisk scale is thick. Even a thinned version of this is enough to repel any sword or spear attack.\n\nThat strength is what makes these scales so valuable to our craft.", objectives = "Obtain the Axetail Basilisk Matriarch Scales.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40210] = { id = 40210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time Well Spent", description = "Unfortunately, {name}, you have learned all that I have to teach. I am pleased we were each able to achieve our goals in this partnership.\n\nGo now and share what you've learned with your allies in Dalaran. I'm sure they'd be eager to share in your training.", completion = "<Namha listens to your tales with wide eyes and an eager ear>\n\nThat's it, {name}. You've inspired me. I've been stuck in this floating city for far too long. It's time to get out there and see the world again.", objectives = "Tell Namha of your time with the night elves in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40211] = { id = 40211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demon Flesh", description = "Something we haven't really explored yet, {name}, are the creatures of Suramar. Specifically, the demons.\n\nNow I certainly don't praise what they are, but you can't ignore the fact that some of their creatures have especially tough hides.\n\nWe could take a lesson from the demon hunters and use those hides to our advantage against the demons. I'll be damned though if I know the first thing about working with demon hide.\n\nPerhaps there's someone in Suramar who can help...", completion = "I says to him, I go, \"The world is on the cutting edge of the knife, and we, we're just the shavings!\"\n\nAnd he says to me, he says, \"But then who'll feed the sabers?!\"\n\nWait... who are you? Leatherworking? Oh... right. I, I was once a great leatherworker...", objectives = "Search for a master leatherworker in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40212] = { id = 40212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrong End of the Knife", description = "There he is! The man that isn't there! He's... he's...\n\nWait... no, I'm sorry. My thoughts, they're just all over place lately. Ever since my exile, things have been a bit fuzzier than normal.\n\nIf you wish to learn from me before I completely lose my mind, then do me a favor, and kill those traitors who sided with the demons and exiled me.", completion = "Green is good. Green is good. Green is good? No way!\n\nOh, it's you {name}. Right, you needed something?\n\nWait, they're dead? And you slew them? Fantastic!", objectives = "Kill the traitor leatherworkers, Feorias, Tallian, and Syana.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40213] = { id = 40213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hounds Abound", description = "I'll invite him to tea. That'll show him! He'll see the leather doll and say, \"When did SHE get here?!\"\n\nI mean... sorry, {name}. My mind goes to strange places. You want to know about the demons, the ones with durable hides?\n\nBefore I was exiled I saw such beasts roaming our cities. Fel hounds, they are called. Slay them and bring me their corpses.\n\nWe can discuss their hides afterwards.", progress = "We met on the lake. It was spring and she wore ley lilies...", completion = "Hey {name}! Come here and listen. You hear it don't you? Come on, I know you hear it!\n\nWhat are those infernal things you're dragging behind you? Fel hounds? For me?\n\nYou have a strange taste in gifts for your friends, {name}.", objectives = "Obtain 5 Fel Hound Corpses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40214] = { id = 40214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Tanning", description = "Listen, you. I'm not sure when the crazy side of me will come out again, so let's make our time together short.\n\nYou want to learn how to make armor to rival the demons? Follow my instructions and you'll have an excellent grasp on the procedures.", progress = "You're really here, right?\n\n<Stalriss reaches out and pinches you>", completion = "Yes, you've done it, {name}. Good work.\n\nNow go, before I do or say something I'd regret, but probably won't remember.", objectives = "Craft a pair of bracers for Stalriss using the tanning rack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40215] = { id = 40215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mounting Made Easy", description = "{name}, I'm glad you're here. I confess: I've been working on a secret project behind your back. Behold: the Stonehide Leather Harness! Now, we simply need to find a mount worthy of such a piece of art.\n\nThe vrykul sing songs of a snow-white elderhorn with endless stamina. Find it, place the harness on it, and tame it.", completion = "Now that's a beast worth riding. Here's the pattern for that harness, if you want one for yourself.", objectives = "Capture the Great Northern Elderhorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40216] = { id = 40216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hunter at Heart", description = "Addie's one heck of a writer, but I've never seen her hold a rifle. She's keen on learning how to hunt, but who's ever heard of a gnome hunter? \n\nYou seem to have a knack dealin' with amateurs, so maybe you'd be willin' to let the gnome tag along on a hunt? She could learn a thing or two by shadowing someone with your skill.\n\nYa best start off with some small game. We don't want the lass to get discouraged.", progress = "Keep an eye on the gnome while you're huntin'. She's never held a rifle before.", completion = "You haven't got any holes in ya, I guess that means Addie's aim isn't as bad as I thought!", objectives = "Help Addie learn to hunt by killing wildlife in Pinerock Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40217] = { id = 40217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Offering of Ammo", description = "The mountains have seen many new travelers pass through their valleys, some without an understanding of our traditions.\n\nOur leaders have turned their focus to more pressing matters, but Losro and I cannot ignore the recent arrival of hunters in the nearby basin.\n\nThey hunt with guns and gadgets, forgoing the experience of hunting with a bow and arrow.\n\nWhile I know that some will remain stuck in their ways, perhaps an offering of arrows will encourage these outsiders to hunt the way we always have.", completion = "We gave up usin' that kind of ammo long ago! Don't worry though, we won't let the gift go to waste. I'm sure we can use the arrows for kindling.", objectives = "Deliver the Quiver of Arrows to Hemet Nesingwary at Nesingwary's Retreat.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40218] = { id = 40218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Debt Repaid", description = "I have a few urgent matters to take care of, but soon after I will make my way to Dreadscar Rift and aid you with your summoning.\n\nYou should warn Ritssyn to keep his distance. I'll be there to repay my debt to you, not to speak to the hypocrite who chose the council over his friends.", completion = "It appears Kira travels faster than your word. She arrived moments ago, though her eyes purposely avoided mine.\n\nIn gaining her trust, you accomplished something I could not. With her help, we should be able to summon the gateway.", objectives = "Speak to Ritssyn Flamescowl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40219] = { id = 40219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Defiance of Deathwing", description = "It was in this place, ages ago, that Huln Highmountain challenged the great Deathwing.\n\nToday we shall re-live moments of that day through the eyes of our ancestors.\n\nFor this next part of the spirit journey, we must seek out the three braziers set down many ages ago so that those who would follow in the footsteps of Huln might witness his deeds.", progress = "You are learning parts of our history few outsiders have ever known.", completion = "And so it was that Huln Highmountain came to this mountain, freeing the drogbar slaves of Deathwing, and came into possession of the Hammer of Khaz'goroth.", objectives = "Witness 3 Visions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40220] = { id = 40220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thorny Dancing", description = "The Thistleleaf sprites have gone completely mad.\n\nI suspect they are being manipulated by some very mischievous Thorndancers.\n\nPlease, friend of the forest, seek out these seductive troublemakers and bring peace to the shallows.", progress = "Have you dealt with those Thorndancers yet?", completion = "That should set those vexing Thorndancers on their way.", objectives = "Defeat 3 Thistleleaf Thorndancers in the Lunarwing Shallows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40221] = { id = 40221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spread Your Lunarwings and Fly", description = "These poor faerie dragons are being tortured!\n\nWhat's worse, when the thistleleaf become bored they ensnare their victims to continue their torment later.\n\nThis behavior is simply unacceptable.\n\nPlease free any trapped Lunarwings you can find.", completion = "On behalf of the Lunarwings, thank you.", objectives = "Save 8 Trapped Lunarwings in the Lunarwing Shallows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40222] = { id = 40222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Imp Mother's Tome", description = "See this giant cave? There's a terrifyingly powerful imp mother inside.\n\nBut that's not the good part. The good part is what she has.\n\nApparently, she's some kind of keeper of fel secrets. She's in there performing profane Legion rites and scribing them into a book.\n\nWe need that power! We need her tome!", progress = "Do you have it?", completion = "Can you feel the power emanating from the book? I cannot wait to learn its secrets.", objectives = "Obtain the Tome of Fel Secrets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40223] = { id = 40223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 DH-Mardum - Small Treasure Chest 008" }
quests[40224] = { id = 40224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hammer in the Deep", description = "<Thrall listens intently.>\n\nYou found it! The Doomhammer fell to the Crumbling Depths... But the Legion remains a step ahead of us. If we hurry, we can follow the demon Geth'xun and retrieve the hammer before any more of this realm is corrupted.\n\nTherazane will open a portal directly there. Let's go!", progress = "What of the Doomhammer?", completion = "The orcs had a prophecy about the Doomhammer. It was said that a stranger will raise the hammer high, and with it, justice shall reign. Maybe... maybe YOU were meant to be that stranger all along.\n\nCome, {name}. The Earthen Ring needs you. And Azeroth needs us.", objectives = "Use Therazane's Portal to travel to the Crumbling Depths. Accompany Stormcaller Mylra and Thrall to recover the Doomhammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40225] = { id = 40225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ring Reforged", description = "Speak with Nobundo, and take your place around the circle, {name}. The Earthen Ring will rise again, with you as its leader!\n\nWithin these stones stands the legendary Heart of Azeroth, which we can use as a base of operations. Perhaps the power of your artifact can unseal the hidden chambers...", progress = "The Alliance and Horde are in chaos. If we are to save Azeroth, we {class} must bind together!", completion = "The Earthen Ring rises once more to defend Azeroth. You will be our Farseer, {name}, and we will be your instruments. Only by working together can we preserve our world.\n\nWe are yours to command, Farseer.", objectives = "Speak with Nobundo and take your place as the head of the Earthen Ring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40226] = { id = 40226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remnants of the Sashj'tar" }
quests[40227] = { id = 40227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad Intentions", description = "Suramar is lost.\n\nOur leaders struck a dark bargain, accepting the Legion as our allies. We were meant to be heroes, guardians - the people resting here. We are not like them any more. I cannot live with them.\n\nBut cut off from the Nightwell, we wither and devolve into a mindless existence. An existence without release or dignity, as you can see even here...\n\nI rejected both of these options and found myself here. I will find a third way.", progress = "Why do you seek to dissuade me?", completion = "Honeyed words from a stranger. While comforting, they do not shake my resolve. Come, at this rate I will wither before we are through.", objectives = "Speak with Thaedris Feathersong in Tel'anor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40228] = { id = 40228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scout It Out", description = "You've proven that a gnome can shoot a rifle, and that's no easy feat, but a true test of Addie's skill will be to see if she can track down an elusive beast.\n\nRumor has it that a ravenous roc circles the basin, cursed by harpy magic, but no one's seen the beast up close.\n\nTake this flare, and shoot it into the sky once you've spotted the roc. When we see the signal, the huntin' party will rush in and help bring down that magnificent bird!", progress = "Don't just stand there, head out into the basin and find that bird!", completion = "That was a kill I won't soon forget!\n\nAddie will write the tale of our adventures here today, but not many will believe that a gnome hunter took down a beast ten times her size.", objectives = "Kill Irewing after sending up a flare, signaling his location.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40229] = { id = 40229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Step into the Dark", description = "With the threat to my people quelled, I believe it is time to introduce you to my kin.\n\nMeet me at Stonedark Grotto, and you will see where we live.", completion = "Welcome to our humble home. You are free to move about here from now on.", objectives = "Speak with Navarrogg at Stonedark Grotto.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40230] = { id = 40230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, the Clawdacity!", description = "The leader of the Cavemoss makrura, Clawdayshus, has been ordering raids into the Cavemoss village to steal the young for snacks.\n\nThis isn't going to do at all. In order to prove their power, Murky and the tadpoles must destroy him as well!\n\nThis is a job for murlocs.\n\nMindmeld with Murky in his egg and show him how it's done!", progress = "Clawdayshus is ruthless. Murky must stop him.", completion = "You did it! Murky will make a great leader for the next generation of the murlocs here.\n\nI can't help but feel sad over losing my little buddy, but you've got to let them go sometime.", objectives = "Mindmeld with Murky and defeat Clawdayshus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40231] = { id = 40231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brood Queen's Court: Count Nefarious" }
quests[40232] = { id = 40232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brood Queen's Court: King Voras" }
quests[40233] = { id = 40233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brood Queen's Court: Overseer Brutarg" }
quests[40234] = { id = 40234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brood Queen's Court: General Volroth" }
quests[40235] = { id = 40235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abrogator Arbitrator", description = "Da bums in Highmaul refuse to see dey are on da way out. Me, I'm gettin' while da gettin' is good. Da sooner youse bring me a bunch of Apexis Crystals, da sooner I can get off dis stupid island. Da amount required is very precise!", progress = "I can feel da power of da crystals! Give dem to me!", completion = "Finally! Today is da day I can get out of here!\n\nIf not I'll need more of dem to try again.", objectives = "Kluk'kluk wants you to bring him 14958 Apexis Crystals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40236] = { id = 40236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dawning Light", description = "It was a miracle that you were able to survive, {name}. It is with great sorrow that I have to say that Grand Master Hight was not so lucky. His spirit now rests with the ancestors.\n\nNow we must look to a new leader for our order, our broken temple. I have spoken with the other masters and we are all of one mind on this.\n\nWe all agree that new leader should be you, {name}. You have shown strength, wisdom, courage, and kindness beyond measure.\n\nWalk with us to the temple and we will announce our decision.", completion = "Congratulations, Grand Master {name}!", objectives = "Accompany Fearsome Jang and await the masters' announcement.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40237] = { id = 40237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Work Stoppage", description = "We've had enough! The working conditions in the Foundry are intolerable with all the fire and the ogron and the flames and the fire elementals and infernos and marauding adventurers! But especially the heat.\n\nI've had enough! Me and the boys are going to start a work stoppage but we need to hire some security muscle and the only goon from Highmaul I could get to agree to the job only takes payment in Apexis Crystals.", progress = "It's a good thing you took care of Mar'gok or nobody would be available for hire. Ogre security is still effective, right?", completion = "I'd say thanks, but I'm pretty sure that us shutting down the Foundry helps you out more than it helps us. So you're welcome.", objectives = "Bring 20000 Apexis Crystals to the Renegade Ironworker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40238] = { id = 40238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grim Equation", description = "They were waiting for us when we crashed. It was all we could do to establish our small outpost.\n\nEven now they drain the souls of our fallen to fuel their attacks.\n\nDestroy their soul coffers. Free our comrades and let them join the Light.\n\nWhen you have finished, find Y'mera in the field. She has been sorely missed, but she will not have fallen. Of this I am certain.", completion = "Good work. They will return in time, but we can use this advantage.", objectives = "Destroy the three Soul Coffers on the Shattered Fields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40240] = { id = 40240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looted Blacksmith Defender's Cache" }
quests[40241] = { id = 40241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Bonds", description = "Do you like pets, {name}? I love pets. They're so cute!\n\nBut what I really want is more things with which to play with them.\n\nI'm sure Serr'ah over at the Magical Menagerie has some ideas for fun toys. You should go talk to her!", completion = "Oh, those are good ideas! Let's get started.", objectives = "Talk to Serr'ah at the Magical Menagerie shop. Then return to Namha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40242] = { id = 40242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mellok, Son of Torok" }
quests[40243] = { id = 40243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break Weapon Racks" }
quests[40244] = { id = 40244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That Guy in the Costume", description = "Aye, when we were out huntin' on the coast, we ran into this ridiculous lad in in a costume. He says he's tryin ta blend in with the murlocs... but I'm pretty sure he's just not right in the head.\n\nOne of ours stayed behind to keep an eye on him when we headed back to camp... mind checkin' it out?\n\nYe can ask Tamara over there for a ride.", completion = "Hello, adventurer! Here to help me and Murky out?", objectives = "Speak to Tamara and fly to Shipwreck Cove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40245] = { id = 40245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looted Tailoring Defender's Cache" }
quests[40246] = { id = 40246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looted Leatherworking Defender's Cache" }
quests[40247] = { id = 40247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asking a Favor", description = "Caria Felsoul was one of our best... before she answered the Legion's foul call.\n\nShe now wields the Aldrachi Warblades - the soul-rending armaments of the ancient race's greatest champion, who fell only to Sargeras himself.\n\nWe sent a party to track Caria down, but we have not heard from them in some time. Jace has nearly repaired a Legion communicator so we can make contact - we need only a power source.\n\nCould you ask Khadgar for assistance? Our friends in this world are few.", completion = "It's good to see you again. If there's anything I can do to help you take the fight to the Legion, just let me know.", objectives = "Ask Khadgar for a source to power the Legion communicator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40249] = { id = 40249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance Will Be Ours", description = "We aren't going to get our forces anywhere near the Broken Shore without getting knocked out of the sky.\n\nI think it best if you handle this matter yourself - there are none among us more capable on the field of battle.\n\nSave Allari and her men if you can, but the Aldrachi Warblades will do far more for this war than warm bodies.", completion = "What of the others? Did they...?\n\nI see. They gave their lives for a worthy cause - the Warblades will change the tide of this war, mark my words.", objectives = "Take the Aldrachi Warblades from Caria Felsoul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40250] = { id = 40250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suramar - Demon Hunter Daily - Choice Reward Summary - 1" }
quests[40251] = { id = 40251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Kethrazor" }
quests[40252] = { id = 40252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[40253] = { id = 40253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop Gul'dan!", description = "After his defeat at the Black Temple, we brought Illidan's lifeless body here, to be interred forever within the Vault of the Wardens.\n\nGul'dan has found his way through our defenses and is trying to steal the Betrayer's corpse.\n\nEven in death, Illidan's body can be used by the Burning Legion. Gul'dan CANNOT succeed.", completion = "Excellent. You have absorbed the powers of these brutes. Look how strong you have grown!", objectives = "Enter the Vault of the Betrayer, kill Crusher and Sledge, and take their fel power.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40254] = { id = 40254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forged in Fire", description = "The fearsome demon, Immolanth, led a Legion army that conquered and eventually ruled a distant nexus world. \n\nSomehow, the Wardens imprisoned him, then kept him locked up in the chamber to our left. He is contained, but not for long.\n\nThe demon's power is a valuable prize to any demon hunter who can defeat him. Whoever can do so will gain power beyond imagining.\n\nI believe that person could be you, {name}.", progress = "Do you have Immolanth's power, {name}?", completion = "Yes... just look you... surging with new power and knowledge!", objectives = "Kill Immolanth and take his power.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40255] = { id = 40255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Between Us and Freedom", description = "The last of our survivors have fought their way into the final chamber ahead.\n\nOnly one obstacle stands between us and the vault's exit - the leader of this demon invasion, Bastillax.\n\nKill him, take his power, and claim our freedom.", completion = "We escaped the Vault, but our work is far from over.\n\nThe Legion's assault on this world is just beginning.\n\nIf Azeroth is to survive, we may have to work with this... Archmage Khadgar.", objectives = "Kill Bastillax and take his power.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40256] = { id = 40256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Between Us and Freedom", description = "The last of our survivors have fought their way into the final chamber ahead.\n\nOnly one obstacle stands between us and the vault's exit - the leader of this demon invasion, Bastillax.\n\nKill him, take his power, and claim our freedom.", completion = "We escaped the Vault, but our work is far from over.\n\nThe Legion's assault on this world is just beginning.\n\nIf Azeroth is to survive, we may have to work with this... Archmage Khadgar.", objectives = "Kill Bastillax and take his power.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40257] = { id = 40257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demon Hunter Choice 1", description = "PLACEHOLDER" }
