quests[40259] = { id = 40259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demon Hunter Choice 2", description = "PLACEHOLDER" }
quests[40260] = { id = 40260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suramar - Demon Hunter Daily - Choice Reward Summary - 3" }
quests[40261] = { id = 40261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demon Hunter Choice 3", description = "PLACEHOLDER" }
quests[40265] = { id = 40265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Touch of Magic", description = "I always took great pride in my home... and my enchantments. Now it seems both have fallen into ruin.\n\nI can sense the power of a potent enchanter in you, {name}. If you would but sprinkle a bit of magic dust on my once-enchanted belongings, I'm sure you can bring them to life again.", progress = "Just the presence of such a vibrant enchanter gives my home the spark of life!", completion = "It pleases me that you have brought life to my beloved enchantments.\n\nOnce I could accomplish much more than mere parlor tricks... until the source of my power was stolen from me.", objectives = "Sprinkle Arkhana on dormant objects in Tigrid's house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40266] = { id = 40266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Advisor", description = "You may as well assist me while you are here. I require a potion to be made, one that will set things right.\n\nI must conserve my energy until my task is finished, lest I become like these miserable wretches scrabbling at the cobblestones. There is coin in it for you, since I will not be needing it soon.\n\nThe harpies around here cannot resist cliffthorn. It is what drew them to Tel'anor in the first place. \n\nYou should find plenty just outside this building.", progress = "<Thaedris seems lost in thought as he gazes towards the city of Suramar.>", completion = "<Thaedris stirs from his thoughts as you approach.>\n\nThese will be sufficient, {race}.\n\n Cliffthorn is a deadly poison, and will be perfect for my needs.", objectives = "Collect 8 Cliffthorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40267] = { id = 40267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unexpected Message", description = "Ah, Felo'melorn. I am familiar with this weapon. \n\nFor ages the Council of Tirisfal attempted to recover the blade. Its control over the primal forces of fire would be devastating in the wrong hands. \n\nAs luck would have it, an associate of mine, Archmage Modera has recently uncovered some information on this artifact. This crystal contains a message from her.\n\nI suggest you start your search there. The portal over there will bring you back to the city.", completion = "{name}, I'm glad you came.\n\nI've found information on just the thing we need to turn this war in our favor.", objectives = "Discover Archmage Modera's message by using the Glowing Resonate Crystal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40268] = { id = 40268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharion's Vault Treasure" }
quests[40269] = { id = 40269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torok's Bluff Treasure" }
quests[40270] = { id = 40270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of Atonement", description = "Felo'melorn, the runeblade of the kings of Quel'Thalas. It was said to harness the very essence of flame and after being reforged by Kael'thas could even stand against the legendary Frostmourne.\n\nWe thought that the blade was lost with Kael'thas's death but an associate of mine has a lead on where it may be located.\n\nWe need every advantage we can get and with Felo'melorn in your hand the Legion surely will tremble!\n\nAh, our company is here.", completion = "Our next journey will be to Icecrown, {name}.\n\nThere, in the heart of the Scourge, we will find Felo'melorn.", objectives = "Speak to Archmage Modera's associate at the Dalaran Crater within Hillsbrad Foothills", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40272] = { id = 40272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Village - Medium Treasure 001 - twh" }
quests[40273] = { id = 40273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Temple of Elune - Medium Treasure 001 - bic" }
quests[40274] = { id = 40274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 DH-Mardum - Small Treasure Chest 010" }
quests[40276] = { id = 40276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Maelstrom Beckons", description = "Can you feel it, shaman? Here, in the heart of Azeroth, where earth and wind and waves clash together - it is as if one can speak directly with the world.\n\nThe artifact you wield houses great power but even greater potential. Carry it below and seek out the ancient elemental altar overlooking the fury of the maelstrom. From there, you can commune with Azeroth and imbue your artifact with even greater abilities. Do so, and then share with me what you have learned!", completion = "I sense that your work here has only begun. As you get more familiar with your artifact, you will be able to continue augmenting its power.\n\nThe others are watching you carefully. You have become a symbol of hope in our struggle against the Legion!", objectives = "Locate the Ancient Elemental Altar and imbue your artifact with a new power.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40277] = { id = 40277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight Night: Tiffany Nelson" }
quests[40278] = { id = 40278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Beasts's Bidding" }
quests[40279] = { id = 40279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training with Durian", description = "Show me that you truly have gained the trust of your companions.", objectives = "Defeat Durian Strongfruit in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
