quests[40363] = { id = 40363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pristine Houndstooth Hauberk", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in Dalaran's archaeology shop.", objectives = "Put the artifact on display.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40364] = { id = 40364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bubble Trouble", description = "{class}! The sea giants have already eaten half of my kin.\n\nWe are helpless in these accursed bubbles. I beseech you to get us out of here.\n\nTake heed. These bubbles are strong. You will need something that is extremely sharp to pierce them.", progress = "Move quickly, {class}! These sea giants have an insatiable appetite!", completion = "There is no glory or honor in being digested.", objectives = "Collect a piece of Needle Coral and then rescue 5 Captured Vrykul in Azuregale Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40368] = { id = 40368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turtle Powered", description = "In order to locate and purify the source of the corruption I am going to need an elemental focus.\n\nThe turtles around here have developed scales that can focus and amplify their innate magics. Bring back some snapper scales and we will have these waters purified in no time!", progress = "Remember, the scales need to be whole to be of any use as a focus.", completion = "These will do nicely.", objectives = "Collect 7 Shimmering Snapper Scales.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40369] = { id = 40369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifact XP - Ironbranch" }
quests[40370] = { id = 40370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purge the Unclean", description = "Do you feel it in the air, {race}? The stage is set for us to make things right.\n\nWhile you were busy I was able to track down the elder elemental that rules these waters. Its name is the Azurefall Guardian and it resides within the channels below Tel'anor.\n\nTake the ritual focus, it should help you during the battle.", progress = "Did you find the source of the corruption?", completion = "It is done. Already I can feel the corrupting presence washing away.\n\nThank you, {name}. You have done this place a great service.", objectives = "Defeat the corruption in the Azurefall Guardian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40373] = { id = 40373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Direction", description = "{name}, as leader of the Illidari in Lord Illidan's absence, you must choose your second-in-command.\n\nKayn or Altruis. You can only choose one.\n\nThe chosen shall become your personal champion, and their ideology will color our decisions for the Illidari going forward. No matter who is chosen, our mission remains unchanged.\n\nIf you need a reminder of our past, gaze into the Pool of Judgment. Remember the sacrifices that forged us into demon hunters. Speak to me when you are ready to choose.", progress = "Have you made a choice?", completion = "I see. I support you no matter your choice. With this new beginning, we shall rebuild the Illidari.", objectives = "Choose between Kayn and Altruis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40374] = { id = 40374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Direction: Obtained Kayn" }
quests[40375] = { id = 40375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Direction: Obtained Altruis" }
quests[40378] = { id = 40378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enter the Illidari: Ashtongue", description = "Lord Illidan has placed you in charge. Now, we just need the rest of our Illidari attack force.\n\nThere are three Burning Legion gateways ahead. Activate them and our Illidari will pour through from the Black Temple.\n\nLike most Legion constructs, the gateways are powered by souls. I think we have provided enough to activate this first one, don't you? Let us bring in our Ashtongue forces.", progress = "{name}, I remind you that we need our Ashtongue forces to be brought through the gateway back on Despair Ridge.", completion = "I saw them run by. Not the most impressive of our troops, but the Ashtongue have proven effective in the past.", objectives = "Summon in your Ashtongue forces by activating the Legion Gateway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40379] = { id = 40379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enter the Illidari: Coilskar", description = "The next gateway's down on the Molten Shore. Our Coilskar forces are waiting at the Black Temple on the other side.\n\nPersonally, I wouldn't have chosen to bring our naga allies. But, their leader did swear fealty to Lord Illidan. I suppose we'll see.\n\nWe'll have to find a way to power the gateway's activator. Like this last gateway, it runs on souls.\n\n<Allari the Souleater grins as Sevis says this.>", completion = "Grim business, but we've all sacrificed just about everything to get to where we are.\n\nWe will do ANYTHING it takes to defeat the Burning Legion. Anything.", objectives = "Feed a soul into the Legion Gateway Activator and then use it to summon in your Coilskar forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40380] = { id = 40380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifact XP - Thondrax" }
quests[40381] = { id = 40381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifact XP - Darkfiend Assassin" }
quests[40382] = { id = 40382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifact XP - Jinikki the Puncturer" }
quests[40383] = { id = 40383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifact XP - Kiranys Duskwhisper" }
quests[40384] = { id = 40384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Needs of the Hunters", description = "The eagle appears to have a message for you:\n\n\n\nThe time has come to strike back at the Legion.\n\nMeet me at Hunter's Reach in Dalaran as soon as you can.\n\n-Emmarel Shadewarden", completion = "Your reputation precedes you, {name}.\n\nIt is important that we speak.", objectives = "Speak with Emmarel Shadewarden in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40385] = { id = 40385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spear in the Shadow", description = "Many years ago, a corrupted nightsaber hunted my people. Our chieftain, Dorro Highmountain, took Talonclaw and pursued the beast, but never returned.\n\nI have heard tales of a fearsome nightsaber that now stalks the mists of Stormheim. My brother and I believe this to be our ancient foe.\n\nThe weapon must be there too! If we kill the beast and reclaim the spear, it will be of great use against the Legion.", completion = "So the Bane of the Highmountain is dead and Talonclaw is recovered! Well done, {name}!\n\nI mourn the loss of Apata and Wuho. They will be greatly missed in the conflict to come.", objectives = "Hunt down Highmountain's Bane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40386] = { id = 40386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Khadgar Arrival" }
quests[40388] = { id = 40388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huln's War - Shadowsong", description = "Someone with whom I believe you are familiar commands in the battlefield below.\n\nJarod Shadowsong speaks highly of you, and has requested that you join him in battle.\n\nHe has plans to put an end to this fight.", completion = "I am happy to see you, great ally.", objectives = "Meet with Jarod Shadowsong in the battlefield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40389] = { id = 40389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Treasure - Skyhorn Kite Created" }
quests[40390] = { id = 40390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallowed Ground" }
quests[40391] = { id = 40391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Me To Your Leader", description = "I am glad you are here, {name}.\n\nThis... Khadgar, the archmage who found my message, has called a meeting.\n\nHe wishes to meet us at the entrance to the city as soon as possible.\n\nWill you accompany me? I have the strangest feeling that he will not be alone.", completion = "Hello again, champion. I see we are all here now.", objectives = "Meet with Khadgar in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40392] = { id = 40392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Marksman", description = "Time is of the essence! If Alleria and Thas'dorah are in Legion hands, it is only a matter of time until both are forfeit.\n\nIf you are ready, head to the Broken Shore to meet with Ranger-General Windrunner.\n\nShe has lent her personal hippogryph to fly you down to the surface.", completion = "The Farstriders have been interrogating captured demons.\n\nOne of the vile creatures claims to know the whereabouts of someone... crucial to our cause.", objectives = "Take the hippogryph from Krasus' Landing down to the Broken Shore and meet with Vereesa Windrunner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40395] = { id = 40395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Timewalking \"Heroic\" Random - Nth", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40397] = { id = 40397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[40398] = { id = 40398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaman Shrine - Stormheim Water 01 - DGK" }
quests[40399] = { id = 40399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar - Vignette: Sailor's Nightmare - twh" }
quests[40400] = { id = 40400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clandestine Operation", description = "You have long been a trusted hero of the Alliance, {name}. And like the rest of us, you have endured many hardships to reach this point.\n\nNow, I must ask even more of you. Will you hear me out?", progress = "Now you must decide whether you will stand with me.", completion = "The time to make our move is now.", objectives = "Speak to Vereesa Windrunner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40401] = { id = 40401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Way Back In", description = "I must get back into Suramar.\n\nI was exiled unfairly! I cannot live out here like this. I need the Nightwell's energies...\n\nI saw a message carved into a wall a few days ago. There is someone in the Water Gardens who can smuggle people into the city.\n\nIt said \"We shall drink of the Well again.\"\n\nI cannot survive a confrontation with the guards again. Will you go in my stead? Once I am back in the city I can repay you.", progress = "Who are you to seek passage into Suramar?", completion = "I hope for both of our sakes that you were not followed. We must work quickly, considering how close I am.", objectives = "Find the smuggler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40402] = { id = 40402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clandestine Operation", description = "As you well know, I have opposed the Horde at many turns. The orcs have taken... so much from me. From my family.\n\nYet I have witnessed your deeds firsthand, {name}. I have seen you fight for Azeroth time and again. And like the rest of us, you have endured many trials and hardships to reach this point.\n\nNow, I must ask your help. Will you hear me out?", progress = "Now you must decide whether you will stand with me.", completion = "The time to make our move is now.", objectives = "Listen to Vereesa Windrunner's tale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40403] = { id = 40403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clandestine Operation", description = "It is no small matter for me to seek the aid of a blood elf. Your leaders have turned their backs on the sacrifices made by my family and so many others.\n\nYet I have witnessed your deeds firsthand, {name}. I have seen you fight for Azeroth time and again. And like the rest of us, you have endured many trials and hardships to reach this point.\n\nNow, I must ask your help. Will you hear me out?", progress = "Now you must decide whether you will stand with me.", completion = "The time to make our move is now.", objectives = "Listen to Vereesa Windrunner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40404] = { id = 40404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[40405] = { id = 40405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bristlemaul" }
quests[40406] = { id = 40406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luggut the Eggeater" }
quests[40407] = { id = 40407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Azeroth", description = "The Burning Legion devastated us at the Broken Shore - the greatest army this world has ever known reduced to cinders in mere moments. Our weapons glanced off of their armor... our spells lost in a sea of fel fire.\n\nWe need weapons capable of destroying Sargeras and his minions while we still have a chance.\n\nThe greatest paladins the world over have gathered at Krasus' Landing to discuss our next move - we're only missing you.", sourceObjective = "Join the greatest paladins of Azeroth at Krasus' Landing.", sourceObjectiveStatus = "unverified-source-field" }
quests[40408] = { id = 40408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Legend", description = "Our gathering has identified several weapons of immense power. In the right hands, these holy artifacts give us a fighting chance against the Legion.\n\nWe cannot pursue all of them at once. We risk too much if we spread ourselves that thin. We must agree on where our efforts are best focused.\n\nThat is why I asked you here, {name}. As one of our greatest champions, you must be our voice of reason and decide our next move.", completion = "Excellent choice! There's no time to waste.", objectives = "Select an artifact weapon to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40409] = { id = 40409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashbringer Chosen" }
quests[40410] = { id = 40410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silver Hand Chosen" }
quests[40411] = { id = 40411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truthguard Chosen" }
quests[40412] = { id = 40412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azoran Must Die", description = "You won't have much time before the Legion is aware of your presence on the ship.\n\nWhen the alarm is raised, countless Burning Legion forces will attempt to board the ship through this portal.\n\nI will not let them succeed.\n\nI will guard this portal from enemy reinforcements until you return. It is up to you to slay Azoran and lay waste to his ship.\n\nWe don't have much time... you must attack swiftly and without mercy.", progress = "Has Azoran been slain?", completion = "With Azoran slain, the Legion has been dealt a crippling blow that they will not soon recover from.\n\nYou have my respect, {name}.", objectives = "Defeat Azoran in Felsoul Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40413] = { id = 40413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amateur Hunters" }
quests[40414] = { id = 40414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devouring Darkness" }
quests[40415] = { id = 40415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Well Spent Time", description = "Your respect for our ways has earned you all the knowledge we have to teach. Go now, {name}, and spread our ways to those who fight against the legion.\n\nPerhaps it will help to turn the tide in this war for our world.", completion = "To think that leatherworking has been that ingrained in the highmountain tauren heritage for that long is absolutely amazing.\n\nI suddenly wish I knew more about my own people's past as well as they do.", objectives = "Tell Namha of your time with the tauren in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40416] = { id = 40416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[40417] = { id = 40417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Tanaan!", description = "It is vital that you set your focus on Tanaan Jungle and establish a foothold there, before you are distracted with other matters.\n\nThe Warchief is ready for you inside your Town Hall. It would be wise not to keep him waiting....", completion = "<The Warchief studies a map of Tanaan Jungle and its surroundings, his brow creased with worry.>\n\nAh, Commander {name}! Voice of da Horde in Draenor. Ya done well here, bringin' da fight ta our enemies. Thrall tells me ya exceed his every expectation.\n\nIt be time ta finish dis. Are ya ready?", objectives = "Speak with Warchief Vol'jin inside the Town Hall of your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40418] = { id = 40418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Tanaan!", description = "It is vital that you set your focus on Tanaan Jungle and establish a foothold there, before you are distracted with other matters.\n\nThe King is ready for you inside your town hall along with his full retinue. It would be wise not to keep him waiting...", completion = "<The King is studying maps of Tanaan Jungle and the surrounding area.>\n\n{name}! The Alliance owes you a great debt for establishing this garrison. Thanks to your bravery and commanding leadership, we've fought this war here on Draenor, instead of amongst our own homes and farmsteads.\n\nIt's time now to finish this. Are you ready for the final campaign?", objectives = "Speak with King Varian Wrynn inside the Town Hall of your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40419] = { id = 40419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue Mission", description = "The demon has told us how to open a portal to the world where he says Alleria is being held. You and I can go through and see if there is any truth to his claims.\n\nIn case it's a trap, Magus Solgaze has given me a portal stone to get us back to Dalaran.\n\nThis demonic magic is anathema to the mage, so we must move quickly. I'm ready when you are, {name}.", completion = "We didn't recover Alleria, but at least we have proof she was there. She will be found... I know it!\n\nThas'dorah has long been symbolic of the Windrunner family, but until Alleria's return, it belongs in your hands.\n\nUse it to rally the greatest hunters of Azeroth and drive the Burning Legion back to the abyss!", objectives = "Travel through the portal and rescue Alleria Windrunner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40420] = { id = 40420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felsoul Hold" }
quests[40422] = { id = 40422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: VotW Started" }
quests[40423] = { id = 40423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unethical Adventurers" }
quests[40424] = { id = 40424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Journey", description = "The city's entrances are under heavy guard. He must have another way.\n\nThanks to this wine I am strong enough to make the journey to him. I fear that I will not be able to defend or run if I come under attack.\n\nYou will accompany me, {race}. You and this Astoril are my only chance at surviving now. \n\nI remember when I was leaving the city that there were lamps guiding me here. We should be able to retrace our steps by following them.", progress = "I was worried something had happened to you in the forest. I am glad that I was wrong.", completion = "Excellent. Your part here is done.\n\nRest assured knowing that you have done me a great service.\n\nHere, take this payment. It is a small token for your service.", objectives = "Follow the lamp posts to take Iadreth to Astoril.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40425] = { id = 40425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifact XP - Pollous the Fetid" }
